logic:
class Component extends DCLogic {
  state = {
    zoomIndex: null,
    scale: 1,
    offsetX: 0,
    offsetY: 0,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragOffsetStartX: 0,
    dragOffsetStartY: 0
  };

  noteData = [
    {
      key: "2005",
      label: "Dos Mil Pesos \u00b7 7 de marzo de 2005",
      denomination: "Dos Mil Pesos",
      date: "Bogotá, 7 de marzo de 2005",
      serial: "23960849",
      errorDesc: "Corte diagonal, con recorte asimétrico de esquinas en ambas caras y mariposa",
      height: 687,
      jpg: "uploads/colombia-2000-pesos-error-corte-descentrado-2005.jpg",
      webp: "uploads/colombia-2000-pesos-error-corte-descentrado-2005.webp",
      webp640: "uploads/colombia-2000-pesos-error-corte-descentrado-2005-640.webp",
      alt: "Billete de Dos Mil Pesos de El Banco de la República, Colombia, fechado 7 de marzo de 2005, anverso arriba con el retrato de Santander y reverso abajo, mostrando un corte diagonal descentrado que recorta las esquinas de forma asimétrica"
    },
    {
      key: "2009",
      label: "Dos Mil Pesos \u00b7 19 de agosto de 2009",
      denomination: "Dos Mil Pesos",
      date: "Bogotá, 19 de agosto de 2009",
      serial: "88646801",
      errorDesc: "Corte horizontal descentrado, margen izquierdo ensanchado y borde derecho recortado",
      height: 606,
      jpg: "uploads/colombia-2000-pesos-error-corte-descentrado.jpg",
      webp: "uploads/colombia-2000-pesos-error-corte-descentrado.webp",
      webp640: "uploads/colombia-2000-pesos-error-corte-descentrado.webp",
      alt: "Billete de Dos Mil Pesos de El Banco de la República, Colombia, anverso arriba con el retrato de Santander y reverso abajo, mostrando un corte descentrado que desplaza el diseño impreso hacia un borde del papel"
    }
  ];

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };

  openZoomAt = (index) => {
    this.setState({ zoomIndex: index, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };

  closeZoom = () => {
    this.setState({ zoomIndex: null });
  };

  stopPropagation = (e) => e.stopPropagation();

  zoomIn = () => {
    this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  };

  zoomOut = () => {
    this.setState(s => {
      const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };

  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({
      dragging: true,
      dragStartX: e.clientX,
      dragStartY: e.clientY,
      dragOffsetStartX: this.state.offsetX,
      dragOffsetStartY: this.state.offsetY
    });
  };

  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };

  onPointerUp = () => this.setState({ dragging: false });

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomIndex !== null) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    const notes = this.noteData.map((n, i) => Object.assign({}, n, { openZoom: () => this.openZoomAt(i) }));
    const active = s.zoomIndex !== null ? this.noteData[s.zoomIndex] : null;

    return {
      notes,
      zoomIndex: s.zoomIndex !== null,
      closeZoom: this.closeZoom,
      stopPropagation: this.stopPropagation,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      activeNoteJpg: active ? active.jpg : "",
      activeNoteWebp: active ? active.webp : ""
    };
  }
}
